        -- 1 = always; XWayland games don't set a content type, so 2 (auto) won't trigger.
        direct_scanout = 1,
    },
})

hl.on("hyprland.start", function()
    hl.exec_cmd("hyprpaper")
    -- hl.exec_cmd("env LC_TIME=en_GB.UTF-8 waybar")
    hl.exec_cmd("dunst")
    hl.exec_cmd("walker --gapplication-service")
    hl.exec_cmd("elephant")
    hl.exec_cmd("eww --config ~/.config/waybar/eww daemon") -- control-center flyout; starts ready so the first click on the Waybar button opens instantly
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("dbus-update-activation-environment --systemd --all")
    hl.exec_cmd("xembedsniproxy")
    hl.exec_cmd("~/.config/hypr/scripts/xwl-clipbridge") -- forward X11 clipboard (Wine/Proton games) to Wayland regardless of focus
    hl.exec_cmd("systemctl --user start hyprpolkitagent")

    -- Apps opened at login, in their usual places (scripts/autostart-apps starts
    -- them). These placement rules are switched off again after two minutes, so
    -- opening the same apps by hand later behaves like any other window.
    local startup_rules = {
        hl.window_rule({
            name = "startup-signal",
            match = { class = "^signal$" },
            workspace = "3 silent",
        }),
        hl.window_rule({
            name = "startup-discord",
            match = { class = "^discord$" },
            workspace = "3 silent",
        }),
        hl.window_rule({
            name = "startup-faugus",
            match = { class = "^io\\.github\\.Faugus\\.faugus-launcher$" },
            workspace = "1 silent",
            float = true,
            size = { 430, 610 },
            move = { 1901, 333 },
        }),
    }
    hl.timer(function()
        for _, rule in ipairs(startup_rules) do
            rule:set_enabled(false)
        end
    end, { timeout = 120000, type = "oneshot" })

    -- WowUp can't start hidden, so the window it opens at login is sent to a hidden
    -- workspace and closed again, which leaves it in the tray. That rule must not
    -- outlive the one window: it is dropped as soon as the window has opened (or
    -- after a minute if none came), so opening WowUp yourself right after login
    -- lands on your workspace like any other window.
    local wowup_rule = hl.window_rule({
        name = "startup-wowup",
        match = { class = "^WowUpCf$" },
        workspace = "special:autostart silent",
    })
    local wowup_pending = true
    local function wowup_done()
        wowup_pending = false
        wowup_rule:set_enabled(false)
    end
    hl.on("window.open", function(window)
        if wowup_pending and window.class == "WowUpCf" then
            wowup_done()
            -- closing it from inside the open event is too early and gets ignored
            local address = window.address
            hl.timer(function()
                hl.dispatch(hl.dsp.window.close({ window = "address:" .. address }))
            end, { timeout = 300, type = "oneshot" })
        end
    end)
    hl.timer(wowup_done, { timeout = 60000, type = "oneshot" })

    hl.exec_cmd("~/.config/hypr/scripts/autostart-apps")
   -- hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme prefer-dark")
   -- hl.exec_cmd("gsettings set org.gnome.desktop.interface gtk-theme Adwaita-dark")
end)

